import{_ as t}from"./chunks/queue-page.NeLK-OZW.js";import{_ as s,o as i,c as a,ag as n}from"./chunks/framework.ieP-ZwyM.js";const g=JSON.parse('{"title":"Running the queue","description":"","frontmatter":{},"headers":[],"relativePath":"operations/queue.md","filePath":"operations/queue.md","lastUpdated":1793171645000}'),r={name:"operations/queue.md"};function o(d,e,l,h,u,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="running-the-queue" tabindex="-1">Running the queue <a class="header-anchor" href="#running-the-queue" aria-label="Permalink to &quot;Running the queue&quot;">​</a></h1><p>Mails, exports, imports, invitations, scheduled jobs and your own jobs run on the database queue (<a href="./../digging-deeper/queues.html">Queues</a>). This page is for operators: where workers run, what to do with failed jobs, and how to deploy.</p><h2 id="where-workers-run" tabindex="-1">Where workers run <a class="header-anchor" href="#where-workers-run" aria-label="Permalink to &quot;Where workers run&quot;">​</a></h2><ul><li><code>serve</code> runs <code>queue.workers</code> (2) workers next to the web server. Set <code>queue.enabled = false</code> (or <code>queue.workers = 0</code>) on web instances that should not run jobs.</li><li><code>rustcms queue:work</code> runs workers alone (a separate process or container). Ctrl-C / SIGTERM lets running jobs finish within <code>queue.shutdown_secs</code> (30 s).</li><li>Run at least one worker somewhere: without one, nothing is mailed, exported or imported, and the panel&#39;s Run now does nothing (requests still answer, the jobs wait).</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # queue.queues, queue.workers workers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # only the \`mail\` queue, 4 workers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # several queues (jobs taken by readiness, not by queue)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --once</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # the jobs ready now (at most 1,000), then exit</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th></th></tr></thead><tbody><tr><td><code>--queue &lt;name&gt;</code></td><td>repeatable; default <code>queue.queues</code></td></tr><tr><td><code>--workers &lt;n&gt;</code></td><td>1 to 64; default <code>queue.workers</code> (at least 1)</td></tr><tr><td><code>--once</code></td><td>for cron or a one-off: deletes old failed jobs, receipts and history first, runs what is ready (at most 1,000 jobs), exits</td></tr></tbody></table><h2 id="built-in-jobs" tabindex="-1">Built-in jobs <a class="header-anchor" href="#built-in-jobs" aria-label="Permalink to &quot;Built-in jobs&quot;">​</a></h2><p>What you see on <strong>System → Queue</strong> besides your own jobs:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Runs</th><th>Timeout</th><th></th></tr></thead><tbody><tr><td><code>mail.send</code></td><td>8</td><td>2 min</td><td>a mail queued with <code>send_later</code></td></tr><tr><td><code>auth.password_reset</code></td><td>5</td><td>2 min</td><td>makes the reset link and mails it; a request older than 15 minutes fails as <code>expired_before_sent</code></td></tr><tr><td><code>auth.invitation</code></td><td>8</td><td>2 min</td><td>makes the invitation link and mails it</td></tr><tr><td><code>admin.export</code></td><td>3</td><td>10 min</td><td>a background export</td></tr><tr><td><code>admin.import</code></td><td>3</td><td>30 min</td><td>an import run</td></tr><tr><td><code>rustcms.schedule.run</code></td><td>1</td><td>the schedule&#39;s, at most <code>queue.max_timeout_secs</code></td><td>a <code>.run</code> or <code>.task</code> schedule&#39;s Run now; never run twice (a run cut by a shutdown fails)</td></tr></tbody></table><p>Job schedules enqueue their own job kinds (<a href="./../digging-deeper/scheduling.html">Scheduling</a>).</p><h2 id="failed-jobs" tabindex="-1">Failed jobs <a class="header-anchor" href="#failed-jobs" aria-label="Permalink to &quot;Failed jobs&quot;">​</a></h2><p><img src="`+t+`" alt="The Queue page filtered on failed jobs, with Retry and Forget"><em>The demo application: System → Queue, failed jobs.</em></p><p>A job fails after its last attempt, at once on a permanent failure (a mail the server refused, a template error), or when no worker knows its kind for <code>queue.unknown_kind_grace_secs</code>. Look at them on <strong>System → Queue</strong> (users with <code>queue.view</code>; acting needs <code>queue.manage</code> too) or:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:failed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # id, kind, attempts, when, the safe error message</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:retry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # or --all: run again (attempts start over)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:forget</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or --all: delete</span></span></code></pre></div><p>Fix the cause first (the SMTP server, the template, a missing permission), then retry. On the Queue page, <strong>Cancel</strong> deletes a job that is still waiting (pending, delayed or stalled).</p><p>Failed jobs and <code>once</code> receipts are deleted after <code>queue.failed_retention_days</code> (30). Finished jobs are listed on the <strong>History</strong> tab for <code>queue.history_retention_days</code> (7; 0 keeps none). Workers delete both about once an hour.</p><h2 id="deploying" tabindex="-1">Deploying <a class="header-anchor" href="#deploying" aria-label="Permalink to &quot;Deploying&quot;">​</a></h2><p>Workers must know a job before code dispatches it: deploy workers first (or together). A job of an unknown kind is given back to other workers, and fails once <code>queue.unknown_kind_grace_secs</code> (1 hour) has passed since the job was created — long enough for a rolling deploy of fresh jobs; a delayed job older than that fails at once on a worker that does not know it.</p><h2 id="delivery" tabindex="-1">Delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Delivery&quot;">​</a></h2><p>Jobs run <strong>at least once</strong>: a run cut after its work but before the queue records it runs again. Built-in jobs are written for it (import rows have receipts, export objects are unique per run, mails carry their run&#39;s <code>Message-ID</code>); write yours with <code>queue::once</code> or idempotency keys.</p><p>Keep the clocks of every instance synchronized (NTP): a lease counts until <code>queue.clock_skew_secs</code> (5 s) after it ends.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../digging-deeper/queues.html#configuration">Queues</a> (every <code>[queue]</code> key)</li><li><a href="./mail.html">Running mail</a></li><li><a href="./retention.html">Data retention</a></li><li><a href="./../digging-deeper/instances.html">Several instances</a></li></ul>`,23)])])}const m=s(r,[["render",o]]);export{g as __pageData,m as default};
